from Crypto.Util.number import long_to_bytes
from sympy import factorint

n = int("")
e = 65537
ct = int("")

print("[*] Factoring the 311-digit RSA modulus locally via SymPy...")
factors_dict = factorint(n)
primes = sorted(list(factors_dict.keys()))

print(f"[+] Found Primes: {primes}")

if len(primes) == 2:
    p = primes[0]
    q = primes[1]
    
    # Decrypt RSA
    phi = (p - 1) * (q - 1)
    d = pow(e, -1, phi)
    pt = pow(ct, d, n)
    
    print(long_to_bytes(pt).decode(errors='ignore').strip())
else:
    print("[-] Local factorization did not complete or found alternative count.")
